#include <vector>
#include <stack>

class Solution {
public:
    std::vector<int> nextGreaterElement(std::vector<int>& arr) {
        int n = arr.size();
        std::vector<int> nge(n, -1);
        std::stack<int> s;

        for (int i = n - 1; i >= 0; i--) {
            // Pop elements smaller or equal to current
            while (!s.empty() && s.top() <= arr[i]) {
                s.pop();
            }

            // Top of stack is next greater element
            if (!s.empty()) {
                nge[i] = s.top();
            }

            s.push(arr[i]);
        }
        return nge;
    }
};
